//! Faithful port of phonemizer 3.4.0's punctuation preserve/restore and
//! the espeak backend's `_postprocess_line`, specialized to the exact
//! configuration KittenTTS uses:
//!   - language `en-us`, `preserve_punctuation=True`, `with_stress=True`
//!   - default separator (phone `''`, word `' '`), `strip=False`
//!   - `language_switch='keep-flags'` (no-op on flag-free output),
//!     `words_mismatch='ignore'` (no-op)
//!
//! Any behavioral divergence is caught by `tests/fixtures.rs`, which replays
//! 47 golden chunks generated by the pinned Python stack.

const DEFAULT_MARKS: &str = ";:,.!?¡¿—…\"«»“”(){}[]";
const DECIMAL_SEPARATORS: [char; 2] = [',', '.'];

#[derive(Debug, Clone)]
pub struct Mark {
    mark: String,
    position: char, // 'B' | 'I' | 'E' | 'A'
}

fn is_python_space(c: char) -> bool {
    // Python `re` \s plus C1 controls it includes; close enough for TTS text.
    c.is_whitespace() || ('\x1c'..='\x1f').contains(&c)
}

fn is_mark_char(c: char, prev: Option<char>, next: Option<char>) -> bool {
    if !DEFAULT_MARKS.contains(c) {
        return false;
    }
    // Decimal separators between two digits stay in the text (phonemizer's
    // `_DECIMAL_SEPARATORS` rule: `(?<![0-9])[,.\-...]` / `[...](?![0-9])`).
    if DECIMAL_SEPARATORS.contains(&c) {
        let prev_digit = prev.map(|p| p.is_ascii_digit()).unwrap_or(false);
        let next_digit = next.map(|p| p.is_ascii_digit()).unwrap_or(false);
        if prev_digit && next_digit {
            return false;
        }
    }
    true
}

fn is_mark_char_at(chars: &[char], i: usize) -> bool {
    let prev = if i > 0 { Some(chars[i - 1]) } else { None };
    let next = chars.get(i + 1).copied();
    is_mark_char(chars[i], prev, next)
}

/// Leftmost-first scan replicating
/// `re.compile(r'(\s*(?:...)+\s*)+').finditer(line)` over the marks language.
fn find_marks(line: &str) -> Vec<(usize, usize)> {
    let chars: Vec<char> = line.chars().collect();
    // char index -> byte index
    let mut byte_of: Vec<usize> = Vec::with_capacity(chars.len() + 1);
    let mut b = 0;
    for c in &chars {
        byte_of.push(b);
        b += c.len_utf8();
    }
    byte_of.push(b);

    let n = chars.len();
    let mut out = Vec::new();
    let mut i = 0;
    while i < n {
        let mut j = i;
        let mut has_mark = false;
        loop {
            while j < n && is_python_space(chars[j]) {
                j += 1;
            }
            let k_start = j;
            while j < n && is_mark_char_at(&chars, j) {
                j += 1;
            }
            if j == k_start {
                break;
            }
            has_mark = true;
        }
        if has_mark {
            out.push((byte_of[i], byte_of[j]));
            i = j;
        } else {
            i += 1;
        }
    }
    out
}

/// Mirrors `Punctuation._preserve_line` (single line, index 0).
fn preserve_line(line: &str) -> (Vec<String>, Vec<Mark>) {
    let matches = find_marks(line);
    if matches.is_empty() {
        return (vec![line.to_string()], vec![]);
    }
    if matches.len() == 1 && matches[0].0 == 0 && matches[0].1 == line.len() {
        return (
            vec![],
            vec![Mark {
                mark: line.to_string(),
                position: 'A',
            }],
        );
    }
    let mut marks = Vec::with_capacity(matches.len());
    for (k, &(s, e)) in matches.iter().enumerate() {
        let mark = line[s..e].to_string();
        let position = if k == 0 && line.starts_with(&mark) {
            'B'
        } else if k == matches.len() - 1 && line.ends_with(&mark) {
            'E'
        } else {
            'I'
        };
        marks.push(Mark { mark, position });
    }
    // Split the line on each mark, mirroring str.split(mark) + rejoin.
    let mut pieces = Vec::with_capacity(marks.len() + 1);
    let mut rest = line.to_string();
    for m in &marks {
        let split: Vec<&str> = rest.split(m.mark.as_str()).collect();
        let prefix = split[0].to_string();
        let suffix = split[1..].join(m.mark.as_str());
        pieces.push(prefix);
        rest = suffix;
    }
    pieces.push(rest);
    (pieces, marks)
}

/// Mirrors `EspeakBackend._postprocess_line` with `strip=False`, `tie=None`,
/// default separator. Input is raw `espeak_TextToPhonemes` output.
fn postprocess_line(line: &str) -> String {
    // .strip().replace('\n', ' ').replace('  ', ' ').
    // Python str.replace replaces ALL non-overlapping occurrences left to
    // right in a single pass; the loop below emulates exactly that.
    let s = line.trim().replace('\n', " ");
    let mut once = String::with_capacity(s.len());
    let mut rest = s.as_str();
    while let Some(p) = rest.find("  ") {
        once.push_str(&rest[..p]);
        once.push(' ');
        rest = &rest[p + 2..];
    }
    once.push_str(rest);
    let s = once;
    // re.sub(r'_+', '_', line)
    let mut t = String::with_capacity(s.len());
    let mut prev_us = false;
    for c in s.chars() {
        if c == '_' {
            if !prev_us {
                t.push('_');
            }
            prev_us = true;
        } else {
            t.push(c);
            prev_us = false;
        }
    }
    // re.sub(r'_ ', ' ', line)
    let t = t.replace("_ ", " ");
    if t.is_empty() {
        return String::new();
    }
    // keep-flags lang switch is a no-op on flag-free output (verified by fixtures).
    let mut out = String::new();
    for word in t.split(' ') {
        let word = word.trim();
        // with_stress=True keeps stresses; tie=None so '_' is appended ...
        let word = format!("{word}_");
        // ... then immediately removed by the empty phone separator.
        let word = word.replace('_', "");
        out.push_str(&word);
        out.push(' ');
    }
    out
}

/// Mirrors `Punctuation.restore` with default separator (word `' '`) and
/// `strip=False`. `pieces` are the phonemized chunks in order.
fn restore(mut text: Vec<String>, mut marks: Vec<Mark>) -> Vec<String> {
    const WORD_SEP: &str = " ";
    let mut punctuated: Vec<String> = Vec::new();
    let mut pos = 0usize;
    while !text.is_empty() || !marks.is_empty() {
        if marks.is_empty() {
            for mut line in text.drain(..) {
                if !line.ends_with(WORD_SEP) {
                    line.push_str(WORD_SEP);
                }
                punctuated.push(line);
            }
        } else if text.is_empty() {
            let joined: String = marks.iter().map(|m| m.mark.as_str()).collect();
            punctuated.push(joined.replace(' ', WORD_SEP));
            marks.clear();
        } else {
            let current = marks[0].clone();
            if current.index() == pos {
                marks.remove(0);
                let mark = current.mark.replace(' ', WORD_SEP);
                if text[0].ends_with(WORD_SEP) {
                    let new_len = text[0].len() - WORD_SEP.len();
                    text[0].truncate(new_len);
                }
                match current.position {
                    'B' => {
                        text[0] = format!("{mark}{}", text[0]);
                    }
                    'E' => {
                        let tail = if mark.ends_with(WORD_SEP) { "" } else { WORD_SEP };
                        punctuated.push(format!("{}{mark}{tail}", text[0]));
                        text.remove(0);
                        pos += 1;
                    }
                    'A' => {
                        let tail = if mark.ends_with(WORD_SEP) { "" } else { WORD_SEP };
                        punctuated.push(format!("{mark}{tail}"));
                        pos += 1;
                    }
                    _ => {
                        // 'I'
                        if text.len() == 1 {
                            text[0] = format!("{}{mark}", text[0]);
                        } else {
                            let first = text.remove(0);
                            text[0] = format!("{first}{mark}{}", text[0]);
                        }
                    }
                }
            } else {
                punctuated.push(text.remove(0));
                pos += 1;
            }
        }
    }
    punctuated
}

impl Mark {
    fn index(&self) -> usize {
        // Single-line input: phonemizer always uses line number 0.
        let _ = &self.mark;
        0
    }
}

pub fn phonemize_chunk(raw_espeak_pieces: Vec<String>, marks: Vec<Mark>) -> Vec<String> {
    restore(raw_espeak_pieces, marks)
}

/// Split one chunk into espeak inputs, mirroring
/// `Punctuation.preserve([chunk])`.
pub fn preserve_chunk(chunk: &str) -> (Vec<String>, Vec<Mark>) {
    preserve_line(chunk)
}

pub fn postprocess_espeak_line(line: &str) -> String {
    postprocess_line(line)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decimal_rule() {
        // "1,5" stays intact (no mark)...
        assert_eq!(find_marks("1,5"), vec![]);
        // ...but "a,5" and "1, 5" split.
        assert!(!find_marks("a,5").is_empty());
        assert!(!find_marks("1, 5").is_empty());
    }

    #[test]
    fn postprocess_matches_python_shape() {
        // '_' separators stripped, words space-joined with trailing space.
        assert_eq!(postprocess_line("h_ˈe_l__oʊ w_ˈɜː_ld"), "hˈeloʊ wˈɜːld ");
    }
}
